package main

import (
	"flag"
	"fmt"
	"os"
	"time"
)

const version = "0.1.0"

const helpText = `bat is a Go implemented CLI cURL-like tool for humans.

Usage:

	bat [flags] [METHOD] URL [ITEM [ITEM]]

flags:
  -a, -auth=USER[:PASS]       Pass a username:password pair as the argument
  -b, -bench=false            Sends bench requests to URL
  -b.N=1000                   Number of requests to run
  -b.C=100                    Number of requests to run concurrently
  -body=""                    Send RAW data as body
  -f, -form=false             Submitting the data as a form
  -j, -json=true              Send the data in a JSON object
  -p, -pretty=true            Print Json Pretty Format
  -i, -insecure=false         Allow connections to SSL sites without certs
  -proxy=PROXY_URL            Proxy with host and port
  -print="A"                  String specifying what the output should contain, default will print all information
         "H" request headers
         "B" request body
         "h" response headers
         "b" response body
  -v, -version=true           Show Version Number

METHOD:
  bat defaults to either GET (if there is no request data) or POST (with request data).

URL:
  The only information needed to perform a request is a URL. The default scheme is http://,
  which can be omitted from the argument; example.org works just fine.

ITEM:
  Can be any of:
    Query string   key=value
    Header         key:value
    Post data      key=value
    File upload    key@/path/file

Example:

	bat beego.me

more help information please refer to https://github.com/astaxie/bat

`

type options struct {
	Auth, Body, Proxy, Print string
	Bench, Form, JSON, Pretty, Insecure, Version, Download bool
	N, C int
}

func usage() {
	fmt.Print(helpText)
	os.Exit(2)
}

func readOptions(args []string) (options, []string) {
	o := options{}
	fs := flag.NewFlagSet("bat", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	fs.Usage = usage
	fs.StringVar(&o.Auth, "auth", "", "")
	fs.StringVar(&o.Auth, "a", "", "")
	fs.BoolVar(&o.Bench, "bench", false, "")
	fs.BoolVar(&o.Bench, "b", false, "")
	fs.IntVar(&o.N, "b.N", 1000, "")
	fs.IntVar(&o.C, "b.C", 100, "")
	fs.StringVar(&o.Body, "body", "", "")
	fs.BoolVar(&o.Form, "form", false, "")
	fs.BoolVar(&o.Form, "f", false, "")
	fs.BoolVar(&o.JSON, "json", true, "")
	fs.BoolVar(&o.Pretty, "pretty", true, "")
	fs.BoolVar(&o.Pretty, "p", true, "")
	fs.BoolVar(&o.Insecure, "insecure", false, "")
	fs.BoolVar(&o.Insecure, "i", false, "")
	fs.StringVar(&o.Proxy, "proxy", "", "")
	fs.StringVar(&o.Print, "print", "A", "")
	fs.BoolVar(&o.Version, "version", false, "")
	fs.BoolVar(&o.Version, "v", false, "")
	fs.BoolVar(&o.Download, "download", false, "")
	fs.BoolVar(&o.Download, "d", false, "")
	if err := fs.Parse(args); err != nil {
		os.Exit(2)
	}
	if o.Version {
		fmt.Println("Version: " + version)
		os.Exit(2)
	}
	return o, fs.Args()
}

// The diagnostics include a source label, independently of how this program is
// split into files. These labels are part of the command's observable format.
func fatalAt(source string, message string) {
	fmt.Fprintf(os.Stderr, "%s %s: %s\n", time.Now().Format("2006/01/02 15:04:05.000000"), source, message)
	os.Exit(1)
}
