package main

import (
	"os"
)

func main() {
	o, args := readOptions(os.Args[1:])
	plan := makePlan(o, args)
	client, transport := makeClient(o)
	defer transport.CloseIdleConnections()
	if o.Bench {
		runBenchmark(o, plan, client, transport)
		return
	}
	response, err := client.Do(plan.request)
	if err != nil {
		fatalAt("bat.go:215", "can't get the url " + err.Error())
	}
	defer response.Body.Close()
	if o.Download {
		download(plan, response)
		return
	}
	printExchange(o, plan, response)
}
