package main

import (
	"bytes"
	"io"
	"mime/multipart"
	"os"
)

// A multipart body is not rewindable, and becomes unreadable once the
// transport has closed it. Keeping its bytes also allows the terminal request
// view to show the body after a successful exchange.
type multipartStream struct {
	reader *bytes.Reader
	closed bool
}

func (b *multipartStream) Read(p []byte) (int, error) {
	if b.closed { return 0, io.ErrClosedPipe }
	return b.reader.Read(p)
}

func (b *multipartStream) Close() error {
	b.closed = true
	return nil
}

func prepareUpload(plan *requestPlan) {
	if !plan.pendingUpload { return }
	plan.pendingUpload = false
	var b bytes.Buffer
	w := multipart.NewWriter(&b)
	for field, path := range plan.files {
		part, err := w.CreateFormFile(field, path)
		if err != nil { fatalAt("httplib.go:322", err.Error()) }
		f, err := os.Open(path)
		if err != nil { fatalAt("httplib.go:328", err.Error()) }
		_, err = io.Copy(part, f)
		f.Close()
		if err != nil { fatalAt("httplib.go:334", err.Error()) }
	}
	for key, value := range plan.fields { _ = w.WriteField(key, value) }
	w.Close()
	plan.body = b.Bytes()
	plan.request.Body = &multipartStream{reader: bytes.NewReader(plan.body)}
	plan.request.ContentLength = 0
	plan.request.Header.Set("Content-Type", w.FormDataContentType())
}
EOF
