// These child processes run this test binary's own main entry point, so tests
// cover exit codes and separated stdout/stderr without any external client.
func TestCommandHelper(t *testing.T) {
	if os.Getenv("BAT_TEST_CHILD") != "1" { return }
	for i, arg := range os.Args {
		if arg == "--" { os.Args = append([]string{"bat"}, os.Args[i+1:]...); main(); os.Exit(0) }
	}
	os.Exit(99)
}

type commandResult struct { status int; out, err string }

func runCommand(t *testing.T, dir string, args ...string) commandResult {
	t.Helper()
	cmd := exec.Command(os.Args[0], append([]string{"-test.run=^TestCommandHelper$", "--"}, args...)...)
	cmd.Env = append(os.Environ(), "BAT_TEST_CHILD=1")
	cmd.Dir = dir
	var stdout, stderr bytes.Buffer; cmd.Stdout = &stdout; cmd.Stderr = &stderr
	err := cmd.Run(); status := 0
	if err != nil { if e, ok := err.(*exec.ExitError); ok { status = e.ExitCode() } else { t.Fatal(err) } }
	return commandResult{status, stdout.String(), stderr.String()}
}

func TestCommandLine(t *testing.T) {
	for _, args := range [][]string{nil, {"-h"}, {"--help"}, {"GET", ""}} {
		r := runCommand(t, "", args...)
		if r.status != 2 || r.out != helpText || r.err != "" { t.Errorf("%q: %+v", args, r) }
	}
	r := runCommand(t, "", "-v"); if r.status != 2 || r.out != "Version: 0.1.0\n" || r.err != "" { t.Fatal(r) }
	for _, c := range []struct{ arg, message string }{{"-j", "flag provided but not defined: -j\n"}, {"-form=invalid", "invalid boolean value \"invalid\" for -form: parse error\n"}, {"-body", "flag needs an argument: -body\n"}} {
		r = runCommand(t, "", c.arg); if r.status != 2 || r.out != helpText || r.err != c.message { t.Errorf("%s: %+v", c.arg, r) }
	}
	r = runCommand(t, "", "GET")
	if r.status != 1 || r.out != "" || !regexp.MustCompile(`^\d{4}/\d\d/\d\d \d\d:\d\d:\d\d\.\d{6} filter.go:35: Miss the URL\n$`).MatchString(r.err) { t.Fatal(r) }
	r = runCommand(t, "", "-b", "-b.N=0", "-f", "-json=false", "http://127.0.0.1:1", "file@/does-not-exist")
	if r.status != 0 || r.out != "" || r.err != "" { t.Fatal(r) }
}

func TestHTTPIntegration(t *testing.T) {
	type requestRecord struct { method, path, body string; header http.Header }
	requests := make(chan requestRecord, 30)
	s := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		b, _ := io.ReadAll(r.Body)
		requests <- requestRecord{r.Method, r.URL.RequestURI(), string(b), r.Header.Clone()}
		if r.URL.Path == "/redirect" { w.Header().Set("Location", "/json"); w.WriteHeader(307); fmt.Fprint(w, "redirect"); return }
		if r.URL.Path == "/file.txt" { fmt.Fprint(w, "abc"); return }
		w.Header().Set("Content-Type", "application/json")
		if r.URL.Path == "/gzip" { w.Header().Set("Content-Encoding", "gzip"); z := gzip.NewWriter(w); _, _ = z.Write([]byte(`{"x":1}`)); z.Close(); return }
		fmt.Fprint(w, `{"x":1}`)
	})); defer s.Close()
	for _, args := range [][]string{{s.URL+"/json"}, {"-print=H", s.URL+"/json"}, {s.URL+"/gzip"}} {
		r := runCommand(t, "", args...)
		if r.status != 0 || r.out != "\n{\n  \"x\": 1\n}" || r.err != "" { t.Fatal(r) }
		got := <-requests; if got.method != "GET" || got.header.Get("User-Agent") != "bat/0.1.0" || got.header.Get("Accept-Encoding") != "gzip, deflate" { t.Fatal(got) }
	}
	r := runCommand(t, "", "-p=false", s.URL+"/json", "name=John")
	if r.status != 0 || r.out != "\n{\"x\":1}" { t.Fatal(r) }
	got := <-requests; if got.method != "POST" || got.body != "{\"name\":\"John\"}\n" || got.header.Get("Content-Type") != "application/json" { t.Fatal(got) }
	r = runCommand(t, "", "-f", "POST", s.URL+"/json", "text=two words")
	got = <-requests; if r.status != 0 || got.body != "text=two+words" || got.header.Get("Content-Type") != "application/x-www-form-urlencoded" { t.Fatal(r, got) }
	r = runCommand(t, "", "POST", s.URL+"/redirect", "a=b")
	got = <-requests; if r.status != 0 || r.out != "\nredirect" || got.path != "/redirect" { t.Fatal(r, got) }
	r = runCommand(t, "", "HEAD", s.URL+"/json"); <-requests
	if r.status != 1 || r.out != "\n" || !strings.Contains(r.err, "Response Json Indent: unexpected end of JSON input") { t.Fatal(r) }
	dir := t.TempDir(); _ = os.WriteFile(filepath.Join(dir, "file.txt"), []byte("previous"), 0600)
	r = runCommand(t, dir, "-d", s.URL+"/file.txt"); <-requests
	data, _ := os.ReadFile(filepath.Join(dir, "file.txt"))
	if r.status != 0 || string(data) != "abcvious" || !strings.Contains(r.out, "Downloading to \"file.txt\"\n") { t.Fatal(r, string(data)) }
}

func TestTLSAndProxy(t *testing.T) {
	s := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "secure") })); defer s.Close()
	r := runCommand(t, "", s.URL)
	if r.status != 1 || !strings.Contains(r.err, "certificate") { t.Fatal(r) }
	r = runCommand(t, "", "-i", s.URL)
	if r.status != 0 || r.out != "\nsecure" { t.Fatal(r) }
	proxy := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.String() != "http://unresolved.invalid/path" { t.Errorf("proxy request: %s", r.URL) }
		fmt.Fprint(w, "proxy")
	})); defer proxy.Close()
	r = runCommand(t, "", "-proxy="+proxy.URL, "http://unresolved.invalid/path")
	if r.status != 0 || r.out != "\nproxy" { t.Fatal(r) }
}

